BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),dates AS(SELECT unnest(ARRAY[DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30']) end_date),
i AS MATERIALIZED(SELECT ts_code,end_date,comp_type,(CASE WHEN comp_type='1' THEN revenue ELSE total_revenue END) IS NOT NULL r_ok,n_income_attr_p IS NOT NULL p_ok,n_income IS NOT NULL n_ok,oper_cost IS NOT NULL cost_ok,operate_profit IS NOT NULL op_ok FROM core_serving.equity_income WHERE end_date IN(DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
b AS MATERIALIZED(SELECT ts_code,end_date,accounts_receiv IS NOT NULL ar_ok,inventories IS NOT NULL inv_ok,acct_payable IS NOT NULL ap_ok,total_assets IS NOT NULL asset_ok,total_liab IS NOT NULL liab_ok,total_hldr_eqy_exc_min_int IS NOT NULL equity_ok,fix_assets_total IS NOT NULL fixed_total_ok,fix_assets IS NOT NULL fixed_old_ok,CASE WHEN fix_assets IS NOT NULL AND fix_assets_total IS NOT NULL THEN fix_assets<>fix_assets_total ELSE NULL END fixed_fields_differ FROM core_serving.equity_balancesheet WHERE end_date IN(DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
c AS MATERIALIZED(SELECT ts_code,end_date,n_cashflow_act IS NOT NULL ocf_ok,c_fr_sale_sg IS NOT NULL salescash_ok,c_pay_acq_const_fiolta IS NOT NULL capex_ok FROM core_serving.equity_cashflow WHERE end_date IN(DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30')),
f AS MATERIALIZED(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,profit_dedt IS NOT NULL d_ok,q_dtprofit IS NOT NULL qd_ok FROM raw_tushare.fina_indicator WHERE end_date IN(DATE '2024-03-31',DATE '2024-06-30',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-03-31',DATE '2025-06-30',DATE '2025-09-30',DATE '2025-12-31',DATE '2026-03-31',DATE '2026-06-30',DATE '2026-09-30') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),
q AS(SELECT dt.end_date,count(*) eligible_codes,count(i.ts_code) income_records,count(b.ts_code) balance_records,count(c.ts_code) cashflow_records,count(f.ts_code) indicator_records,count(*) FILTER(WHERE i.r_ok) revenue_valid,count(*) FILTER(WHERE i.p_ok) parent_profit_valid,count(*) FILTER(WHERE i.comp_type='1') general_comp_codes,count(*) FILTER(WHERE i.comp_type='1' AND i.r_ok AND i.cost_ok) general_gross_margin_inputs,count(*) FILTER(WHERE b.ar_ok) ar_valid,count(*) FILTER(WHERE b.inv_ok) inventory_valid,count(*) FILTER(WHERE b.ap_ok) payable_valid,count(*) FILTER(WHERE b.asset_ok AND b.liab_ok AND b.equity_ok) asset_liability_equity_valid,count(*) FILTER(WHERE b.fixed_total_ok) fixed_assets_total_valid,count(*) FILTER(WHERE b.fixed_old_ok) fixed_assets_old_valid,count(*) FILTER(WHERE b.fixed_fields_differ) fixed_fields_differ,count(*) FILTER(WHERE c.ocf_ok) ocf_valid,count(*) FILTER(WHERE c.salescash_ok) salescash_valid,count(*) FILTER(WHERE c.capex_ok) capex_valid,count(*) FILTER(WHERE f.d_ok) deducted_valid,count(*) FILTER(WHERE f.qd_ok) direct_quarter_deducted_valid,count(*) FILTER(WHERE i.r_ok AND i.p_ok AND c.ocf_ok AND b.asset_ok AND f.d_ok) five_core_inputs FROM base a CROSS JOIN dates dt LEFT JOIN i ON i.ts_code=a.ts_code AND i.end_date=dt.end_date LEFT JOIN b ON b.ts_code=a.ts_code AND b.end_date=dt.end_date LEFT JOIN c ON c.ts_code=a.ts_code AND c.end_date=dt.end_date LEFT JOIN f ON f.ts_code=a.ts_code AND f.end_date=dt.end_date GROUP BY dt.end_date)
SELECT jsonb_build_object('section','current_scope_period_coverage','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q) ORDER BY end_date)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),f AS MATERIALIZED(SELECT DISTINCT ON(ts_code) ts_code,profit_dedt FROM raw_tushare.fina_indicator WHERE end_date=DATE '2026-09-30' ORDER BY ts_code,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),q AS(SELECT a.ts_code,a.name,CASE WHEN f.ts_code IS NULL THEN 'indicator_record_absent' ELSE 'profit_dedt_null' END reason FROM base a LEFT JOIN f ON f.ts_code=a.ts_code WHERE f.profit_dedt IS NULL ORDER BY a.ts_code LIMIT 20)
SELECT jsonb_build_object('section','current_missing_deducted_samples','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),i AS MATERIALIZED(SELECT ts_code FROM core_serving.equity_income WHERE end_date=DATE '2026-09-30'),q AS(SELECT a.ts_code,a.name FROM base a LEFT JOIN i ON i.ts_code=a.ts_code WHERE i.ts_code IS NULL ORDER BY a.ts_code LIMIT 20)
SELECT jsonb_build_object('section','current_missing_income_samples','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb)) FROM q;
COMMIT;
